size(8cm);
void sq(real a, real b)
{ draw((a+1,b)--(a,b+1)--(a-1,b)--(a,b-1)--cycle,blue); }
for (int a=-3; a<=3; a+=2)
for (int b=-3; b<=3; b+=2)
sq(a,b);
draw((-5,0)--(5,0),EndArrow);
draw((0,-5)--(0,5),EndArrow);
label("$x$",(5,0),NNW);
label("$y$",(0,5),ESE);
for (int i=-4; i<=4; ++i) {draw((i,-0.15)--(i,0.15)^^(-0.15,i)--(0.15,i));}
[/asy]

